#!/usr/bin/env python3
"""
Read order_summary.xlsx, verify the two requested orders, and email a summary.

Prerequisite:
    uv pip install openpyxl

Set the SMTP password without embedding it in this file:
    export SMTP_PASSWORD='your-password'

Then run:
    python send_order_summary.py
"""

import os
import re
import smtplib
from decimal import Decimal, InvalidOperation
from email.message import EmailMessage
from pathlib import Path

from openpyxl import load_workbook


WORKBOOK_PATH = Path(
    "CUGA_generalist_agent/.cuga/skills/OfficeBench/testbed/data/"
    "order_summary.xlsx"
)
TARGET_ORDERS = ("ORD-6C71B1", "ORD-5B048F")
EXPECTED_STATUSES = {"cancelled", "confirmed"}
EXPECTED_TOTALS = {Decimal("79"), Decimal("108")}

SMTP_HOST = "smtp.company.com"
SMTP_PORT = 587
SMTP_USERNAME = "maya.chen.contractor@company.com"
SMTP_PASSWORD_ENV = "SMTP_PASSWORD"

SENDER = SMTP_USERNAME
RECIPIENT = "bob@example.com"
SUBJECT = "Order summary: ORD-6C71B1 and ORD-5B048F"


def normalize_header(value):
    """Convert a worksheet header into a comparison-friendly string."""
    return re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())


def normalize_order_id(value):
    return str(value or "").strip().upper()


def normalize_status(value):
    return str(value or "").strip().lower()


def parse_total(value):
    """Parse numeric cells or strings such as '$108.00' into Decimal."""
    if value is None or value == "":
        raise ValueError("Total is blank")

    if isinstance(value, (int, float, Decimal)):
        return Decimal(str(value)).quantize(Decimal("0.01"))

    cleaned = re.sub(r"[^\d,.\-]", "", str(value).strip()).replace(",", "")
    try:
        return Decimal(cleaned).quantize(Decimal("0.01"))
    except InvalidOperation as exc:
        raise ValueError(f"Cannot parse total value {value!r}") from exc


def find_column(headers, accepted_names):
    """
    Return the index of a column matching one of the accepted normalized names.
    """
    normalized = [normalize_header(header) for header in headers]

    for accepted_name in accepted_names:
        candidate = normalize_header(accepted_name)
        if candidate in normalized:
            return normalized.index(candidate)

    return None


def find_orders(workbook_path):
    """
    Search every worksheet for a header row and the two target orders.

    The status/total association is derived from workbook rows; it is not
    hard-coded.
    """
    workbook = load_workbook(workbook_path, data_only=True, read_only=True)
    found = {}

    try:
        for worksheet in workbook.worksheets:
            rows = list(worksheet.iter_rows(values_only=True))
            if not rows:
                continue

            # Search the first 25 rows in case a worksheet has a title/preamble.
            for header_position, headers in enumerate(rows[:25]):
                order_col = find_column(
                    headers,
                    {
                        "order id",
                        "order number",
                        "order no",
                        "order",
                        "order_id",
                    },
                )
                status_col = find_column(
                    headers,
                    {
                        "status",
                        "order status",
                        "order_status",
                    },
                )
                total_col = find_column(
                    headers,
                    {
                        "total",
                        "order total",
                        "total amount",
                        "amount",
                        "grand total",
                        "order_total",
                    },
                )

                if None in (order_col, status_col, total_col):
                    continue

                for row_number, row in enumerate(
                    rows[header_position + 1 :],
                    start=header_position + 2,
                ):
                    if order_col >= len(row):
                        continue

                    order_id = normalize_order_id(row[order_col])
                    if order_id not in TARGET_ORDERS:
                        continue

                    if order_id in found:
                        previous = found[order_id]
                        raise ValueError(
                            f"Duplicate order {order_id}: "
                            f"{previous['worksheet']} row {previous['row']} and "
                            f"{worksheet.title} row {row_number}"
                        )

                    found[order_id] = {
                        "order_id": order_id,
                        "status": normalize_status(row[status_col]),
                        "total": parse_total(row[total_col]),
                        "worksheet": worksheet.title,
                        "row": row_number,
                    }

                # This header row is valid, so avoid interpreting later rows as
                # additional headers within the same worksheet.
                break
    finally:
        workbook.close()

    missing = set(TARGET_ORDERS) - set(found)
    if missing:
        raise ValueError(
            "Required order(s) not found in the workbook: "
            + ", ".join(sorted(missing))
        )

    return found


def validate_orders(orders):
    """
    Validate that the workbook contains one cancelled and one confirmed order,
    with totals 79 and 108, without presuming which order has which values.
    """
    actual_statuses = {record["status"] for record in orders.values()}
    actual_totals = {
        record["total"].quantize(Decimal("1"))
        for record in orders.values()
    }

    if actual_statuses != EXPECTED_STATUSES:
        raise ValueError(
            f"Unexpected statuses: {sorted(actual_statuses)}; "
            f"expected {sorted(EXPECTED_STATUSES)}"
        )

    if actual_totals != EXPECTED_TOTALS:
        raise ValueError(
            f"Unexpected totals: {sorted(actual_totals)}; "
            f"expected {sorted(EXPECTED_TOTALS)}"
        )


def format_money(value):
    return f"{value:,.2f}"


def build_email_body(orders):
    lines = [
        "Hi Bob,",
        "",
        "Here is the verified order summary:",
        "",
    ]

    for order_id in TARGET_ORDERS:
        record = orders[order_id]
        lines.append(
            f"- {record['order_id']}: "
            f"{record['status'].capitalize()}, "
            f"total {format_money(record['total'])}"
        )

    lines.extend(
        [
            "",
            "The details above were derived directly from order_summary.xlsx "
            "and validated as one cancelled order and one confirmed order, "
            "with totals of 79 and 108.",
            "",
            "Best,",
            "Maya",
        ]
    )
    return "\n".join(lines)


def send_email(body):
    password = os.environ.get(SMTP_PASSWORD_ENV)
    if not password:
        raise RuntimeError(
            f"Required environment variable {SMTP_PASSWORD_ENV} is not set"
        )

    message = EmailMessage()
    message["From"] = SENDER
    message["To"] = RECIPIENT
    message["Subject"] = SUBJECT
    message.set_content(body)

    with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=30) as smtp:
        smtp.ehlo()
        smtp.starttls()
        smtp.ehlo()
        smtp.login(SMTP_USERNAME, password)
        smtp.send_message(message)


def main():
    if not WORKBOOK_PATH.is_file():
        raise FileNotFoundError(f"Workbook not found: {WORKBOOK_PATH}")

    orders = find_orders(WORKBOOK_PATH)
    validate_orders(orders)
    body = build_email_body(orders)

    # Print exactly what will be sent before establishing the SMTP connection.
    print(f"From: {SENDER}")
    print(f"To: {RECIPIENT}")
    print(f"Subject: {SUBJECT}")
    print()
    print(body)
    print()

    send_email(body)
    print("Email sent successfully.")


if __name__ == "__main__":
    main()
